import{_ as t,c as i,o,j as e,a2 as n,a}from"./chunks/framework.mqLGQ42V.js";const v=JSON.parse('{"title":"编辑器界面总览 (Interface Overview) - Rive 编辑器","description":"Rive 编辑器是所有创作发生的地方。它分为两大主要模式：设计模式 (Design Mode) 和 动画模式 (Animate Mode)。 在本视频中，我们将带你快速浏览 Rive 编辑器的布局和主要功能区。","frontmatter":{"title":"编辑器界面总览 (Interface Overview) - Rive 编辑器","description":"Rive 编辑器是所有创作发生的地方。它分为两大主要模式：设计模式 (Design Mode) 和 动画模式 (Animate Mode)。 在本视频中，我们将带你快速浏览 Rive 编辑器的布局和主要功能区。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 编辑器界面总览"}]]},"headers":[],"relativePath":"editor/interface/overview.md","filePath":"editor/interface/overview.md","lastUpdated":1774838907000}'),l={name:"editor/interface/overview.md"};function s(h,r,d,c,p,f){return o(),i("div",null,[...r[0]||(r[0]=[e("h1",{id:"编辑器界面总览-interface-overview",tabindex:"-1"},[a("编辑器界面总览 (Interface Overview) "),e("a",{class:"header-anchor",href:"#编辑器界面总览-interface-overview","aria-label":'Permalink to "编辑器界面总览 (Interface Overview)"'},"​")],-1),e("p",null,[a("Rive 编辑器是所有创作发生的地方。它分为两大主要模式："),e("strong",null,"设计模式 (Design Mode)"),a(" 和 "),e("strong",null,"动画模式 (Animate Mode)"),a("。")],-1),e("hr",null,null,-1),e("h3",{id:"🎬-官方视频教程-界面总览",tabindex:"-1"},[a("🎬 官方视频教程（界面总览） "),e("a",{class:"header-anchor",href:"#🎬-官方视频教程-界面总览","aria-label":'Permalink to "🎬 官方视频教程（界面总览）"'},"​")],-1),e("p",null,"在本视频中，我们将带你快速浏览 Rive 编辑器的布局和主要功能区。",-1),e("div",{style:{position:"relative","padding-bottom":"56.25%",height:"0",overflow:"hidden","border-radius":"8px",background:"#000"}},[e("iframe",{src:"https://player.bilibili.com/player.html?bvid=BV1mBBpBuEzK&page=2&high_quality=1&danmaku=0&autoplay=0",scrolling:"no",border:"0",frameborder:"no",framespacing:"0",allowfullscreen:"true",referrerpolicy:"no-referrer",style:{position:"absolute",top:"0",left:"0",width:"100%",height:"100%"}})],-1),n('<p style="text-align:center;color:#666;font-size:0.9em;margin-top:10px;">📺 视频教程：Rive 界面总览（中文字幕）</p><hr><h3 id="区域划分" tabindex="-1">区域划分 <a class="header-anchor" href="#区域划分" aria-label="Permalink to &quot;区域划分&quot;">​</a></h3><p>Rive 的界面主要由以下五个部分组成：</p><h4 id="_1-工具栏-toolbar-位于顶部" tabindex="-1">1. 工具栏 (Toolbar) - 位于顶部 <a class="header-anchor" href="#_1-工具栏-toolbar-位于顶部" aria-label="Permalink to &quot;1. 工具栏 (Toolbar) - 位于顶部&quot;">​</a></h4><p>这里包含了选择工具、绘图工具（钢笔、形状）、文本工具以及最重要的 <strong>模式切换开关</strong>（Design / Animate）。</p><h4 id="_2-层级面板-hierarchy-位于左侧" tabindex="-1">2. 层级面板 (Hierarchy) - 位于左侧 <a class="header-anchor" href="#_2-层级面板-hierarchy-位于左侧" aria-label="Permalink to &quot;2. 层级面板 (Hierarchy) - 位于左侧&quot;">​</a></h4><p>显示当前画板（Artboard）中所有的对象、分组、骨骼和约束。你可以在这里调整图层的上下顺序。</p><h4 id="_3-检查器-inspector-位于右侧" tabindex="-1">3. 检查器 (Inspector) - 位于右侧 <a class="header-anchor" href="#_3-检查器-inspector-位于右侧" aria-label="Permalink to &quot;3. 检查器 (Inspector) - 位于右侧&quot;">​</a></h4><p>这是你调整属性的地方。当你选中一个物体时，可以在这里修改它的坐标、大小、填充颜色、描边属性等。</p><h4 id="_4-舞台-stage-位于中间" tabindex="-1">4. 舞台 (Stage) - 位于中间 <a class="header-anchor" href="#_4-舞台-stage-位于中间" aria-label="Permalink to &quot;4. 舞台 (Stage) - 位于中间&quot;">​</a></h4><p>这是你的画布，是你进行创作和实时预览的地方。</p><h4 id="_5-资源库与状态机面板-assets-state-machine-位于底部" tabindex="-1">5. 资源库与状态机面板 (Assets &amp; State Machine) - 位于底部 <a class="header-anchor" href="#_5-资源库与状态机面板-assets-state-machine-位于底部" aria-label="Permalink to &quot;5. 资源库与状态机面板 (Assets &amp; State Machine) - 位于底部&quot;">​</a></h4><ul><li>在 <strong>设计模式</strong> 下，这里显示你上传的文件（图片、字体等）。</li><li>在 <strong>动画模式</strong> 下，这里是你的 <strong>时间轴 (Timeline)</strong> 和 <strong>状态机 (State Machine)</strong> 面板。</li></ul><hr><h3 id="💡-核心提示-模式切换" tabindex="-1">💡 核心提示：模式切换 <a class="header-anchor" href="#💡-核心提示-模式切换" aria-label="Permalink to &quot;💡 核心提示：模式切换&quot;">​</a></h3><ul><li><strong>设计模式 (F1)</strong>：用于绘图、设置骨骼和准备素材。</li><li><strong>动画模式 (F2)</strong>：用于创建关键帧、混合动画逻辑和测试交互。</li></ul><hr><h3 id="📚-相关阅读" tabindex="-1">📚 相关阅读 <a class="header-anchor" href="#📚-相关阅读" aria-label="Permalink to &quot;📚 相关阅读&quot;">​</a></h3><ul><li><a href="https://help.rive.app./editor/interface/toolbar" target="_blank" rel="noreferrer">了解工具栏详情</a></li><li><a href="https://help.rive.app./editor/interface/hierarchy" target="_blank" rel="noreferrer">掌握层级面板</a></li></ul>',20)])])}const m=t(l,[["render",s]]);export{v as __pageData,m as default};
